import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.DTdEDYjJ.js";const u=JSON.parse('{"title":"使用门槛与运行方式","description":"","frontmatter":{},"headers":[],"relativePath":"guide/requirements.md","filePath":"guide/requirements.md"}'),r={name:"guide/requirements.md"};function i(l,t,n,h,p,s){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="使用门槛与运行方式" tabindex="-1">使用门槛与运行方式 <a class="header-anchor" href="#使用门槛与运行方式" aria-label="Permalink to &quot;使用门槛与运行方式&quot;">​</a></h1><p><strong>先有一台 Mac，以及一个可用的模型 API 或受支持的本机智能体，就能开始。</strong> 云服务器是需要持续在线时的选择。默认 Harness 随应用提供，普通对话不要求先安装另一套执行框架。</p><h2 id="三档使用门槛" tabindex="-1">三档使用门槛 <a class="header-anchor" href="#三档使用门槛" aria-label="Permalink to &quot;三档使用门槛&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想做什么</th><th>需要准备</th><th>需要云服务器吗</th><th>当前范围</th></tr></thead><tbody><tr><td>只在自己的 Mac 使用</td><td>Mac arm64、OpenBot、模型 API 或已绑定本机智能体</td><td>不需要</td><td>已实现，见<a href="/openbot/guide/quickstart.html">快速开始</a></td></tr><tr><td>手机访问自己的 Mac</td><td>Mac 保持运行、可互通局域网、HTTPS Hub 与设备授权</td><td>不需要</td><td>独立原型；USB 任务与 LAN 配对分别已测，LAN 模型任务待验收</td></tr><tr><td>离开本机后持续访问 Bot</td><td>一台持续在线的主机、节点模型配置、受保护访问入口</td><td>可选，也可用常开个人设备</td><td>Linux Node 已实现，手机 App 公网闭环待验收</td></tr></tbody></table><p>源码、安装包、云端实例和手机原型分别验证。当前说明面向0.10.9源码预览；完整范围见<a href="/openbot/guide/status.html">验证状态</a>。</p><h2 id="第一档-先用自己的-mac" tabindex="-1">第一档：先用自己的 Mac <a class="header-anchor" href="#第一档-先用自己的-mac" aria-label="Permalink to &quot;第一档：先用自己的 Mac&quot;">​</a></h2><p>两条路径任选其一：</p><ul><li><strong>模型 API</strong>：保存 Base URL、API Key 和模型名，发送一条消息验证真实回复。</li><li><strong>本机智能体</strong>：先在受支持的 CLI 中完成安装与登录，再从 OpenBot 的“智能体工作空间”显式接入。该绑定 Bot 沿用原执行器的模型、订阅和权限。</li></ul><p>本机使用不要求云商账号、公网 IP、Docker、SSH、Tailscale 或 OpenBot 官方账号。源码运行需要 Node.js 与 npm；取得安装包后按实际版本安装即可。</p><p>本地运行不等于离线推理。模型 API 与多数 CLI 仍需连接其服务商；任务内容的传输取决于你选择的执行器和服务。</p><h2 id="第二档-mac-就是你的-bot-服务器" tabindex="-1">第二档：Mac 就是你的 Bot 服务器 <a class="header-anchor" href="#第二档-mac-就是你的-bot-服务器" aria-label="Permalink to &quot;第二档：Mac 就是你的 Bot 服务器&quot;">​</a></h2><p>Bot 在 Mac 执行，手机作为另一个访问入口，不需要复制一套模型 Key、Bot 或浏览器登录态。当前手机路径使用<strong>独立预览 Node/Hub 与资料目录</strong>，尚未和日常 Mac App 自动合并。</p><p>基本条件：</p><ol><li>Mac 保持开机、未休眠且 Node/Hub 服务运行。</li><li>手机与 Mac 在可互通的局域网；Mac 可以接网线，手机使用该局域网的 Wi-Fi。</li><li>手机信任实际 HTTPS 入口的证书，再完成独立设备配对。</li><li>按授予的范围读取 Bot、交办任务和接收结果；撤销后拒绝读写。</li></ol><p>已有 Android USB 真实任务，以及不使用USB反向隧道的LAN HTTPS配对/撤销记录；<strong>LAN真实模型任务、新扫码入口真机闭环仍待验收</strong>。这些记录不能写成日常安装包的一键手机功能已交付。</p><p>访客 Wi-Fi、校园网或路由器设备隔离可能阻止访问；同一网络名不保证连通。不能用另起一个写入相同数据目录的 Node 来代替 App 整合。</p><p>Mac 休眠、关机或退出服务后，手机不能继续访问它，也不会接替执行。离开局域网后，再选择私有组网或持续在线主机；Tailscale 不是本机使用的前提。</p><h2 id="第三档-再选择持续在线的主机" tabindex="-1">第三档：再选择持续在线的主机 <a class="header-anchor" href="#第三档-再选择持续在线的主机" aria-label="Permalink to &quot;第三档：再选择持续在线的主机&quot;">​</a></h2><p>可使用阿里云、腾讯云、华为云，或自己维护的常开设备。模型与云商可分别选择。</p><p>Linux Node 部署需要 Docker、经过核验的 SSH 连接和私有数据目录。部署者管理更新、备份和网络入口；先按<a href="/openbot/deployment/self-host.html">部署教程</a>验证小任务、接管与取消，再增加负载。官方维护运行环境仍属<a href="/openbot/deployment/hosted.html">规划</a>。</p><p>持续在线不等于所有动作无人审批。失联时控制权与审批按边界暂停，重启后的未完成任务标为中断，不自动重做。</p><h2 id="登录、配对与网络各管什么" tabindex="-1">登录、配对与网络各管什么 <a class="header-anchor" href="#登录、配对与网络各管什么" aria-label="Permalink to &quot;登录、配对与网络各管什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>解决的问题</th></tr></thead><tbody><tr><td>模型连接</td><td>Bot 使用哪个模型、如何调用</td></tr><tr><td>账号登录</td><td>用户身份；不能代替网络可达性</td></tr><tr><td>设备配对</td><td>哪台手机获准访问哪些 Bot</td></tr><tr><td>网络连接</td><td>手机能否到达运行主机</td></tr><tr><td>应用授权</td><td>哪个 Bot 可以代表用户对哪个应用执行哪些动作</td></tr></tbody></table><p>微信 ClawBot 收发消息、微信账号登录和GitHub应用授权是不同入口，不能互相替代设备配对、网络连接或屏幕审批。</p><p>从<a href="/openbot/guide/quickstart.html">快速开始</a>起步，需要多端访问时再阅读<a href="/openbot/deployment/network.html">网络连接</a>。</p>',25)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
